const _groupComposerVoice=Object.create(null);
function groupComposerKey(scope,id){return scope+':'+id;}
function groupComposerVoiceOn(scope,id){return !!_groupComposerVoice[groupComposerKey(scope,id)];}
function groupComposerHTML(scope,id,inputId,placeholder,sendAction,panelId){const voice=groupComposerVoiceOn(scope,id);return `<div class="inputbar chat-inputbar group-chat-inputbar${voice?' voice-on':''}"><button type="button" class="chat-composer-icon chat-voice-toggle" aria-label="切换语音输入" onclick="groupComposerVoiceToggle('${scope}','${id}','${inputId}')">${chatVoiceButtonIcon()}</button><textarea id="${inputId}" rows="1" placeholder="${voice?'输入文字，发送为语音条…':placeholder}"></textarea><button type="button" class="chat-composer-icon chat-emoji-toggle" aria-label="打开表情" onclick="groupComposerPanelToggle('${panelId}','emoji')">${chatEmojiButtonIcon()}</button><button type="button" class="chat-composer-icon chat-function-toggle" aria-label="打开更多功能" onclick="groupComposerPanelToggle('${panelId}','fn')"><span aria-hidden="true"></span></button><button type="button" class="send chat-send" onclick="${sendAction}">${voice?'发语音':'发送'}</button></div>`;}
function groupComposerVoiceToggle(scope,id,inputId){const key=groupComposerKey(scope,id),on=!_groupComposerVoice[key];_groupComposerVoice[key]=on;const ta=$('#'+inputId),bar=ta&&ta.closest('.chat-inputbar'),send=bar&&bar.querySelector('.chat-send');if(bar)bar.classList.toggle('voice-on',on);if(ta)ta.placeholder=on?'输入文字，发送为语音条…':(scope==='pffriend'?'发消息…':scope==='pfgroup'?'发群消息…':'群里说点啥…');if(send)send.textContent=on?'发语音':'发送';if(ta){chatComposerStateSync(ta);ta.focus();}}
function groupComposerPanelToggle(panelId,page){const p=$('#'+panelId);if(!p)return;const next=page==='emoji'?'emoji':'fn',same=p.classList.contains('show')&&p.dataset.page===next;p.dataset.page=next;p.querySelectorAll('.chat-panel-pane').forEach(x=>x.classList.remove('on'));const pane=p.querySelector(next==='emoji'?'.chat-emoji-pane':'.chat-function-pane');if(pane)pane.classList.add('on');p.classList.toggle('show',!same);if(next==='emoji'&&!same)warmStickerImages(S.me.stickers||[]).catch(()=>{});const ta=p.parentNode&&p.parentNode.querySelector('.group-chat-inputbar textarea');if(ta&&document.activeElement===ta)ta.blur();}
function afterGroupComposer(c){const id=c.p==='pfgroup'?'pfg_input':c.p==='pfchat'?'pf_input':'ginput',ta=$('#'+id);if(!ta||ta._groupComposerBound)return;ta._groupComposerBound=1;ta.addEventListener('compositionend',function(){chatComposerReflow(this);chatComposerStateSync(this);});ta.addEventListener('input',function(){chatComposerReflow(this);chatComposerStateSync(this);});ta.addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();if(c.p==='pfgroup')sendPhoneFriendGroup(c.gid);else if(c.p==='pfchat')sendPhoneFriend(c.id);else sendGroup(c.id);}});chatComposerStateSync(ta);}
function chatFunctionItem(label,icon,action){return `<button type="button" class="it" onclick="${action}"><span class="b">${svgIc(icon,25,'currentColor')}</span><span>${label}</span></button>`;}
function chatFunctionPanel(id){const first=[
  chatFunctionItem('相册','image',`cPhoto('${id}')`),chatFunctionItem('图文描述','camera',`cPhotoText('${id}')`),chatFunctionItem('语音通话','phone',`placeCall('${id}','voice')`),chatFunctionItem('视频通话','video',`placeCall('${id}','video')`),
  chatFunctionItem('位置','location',`cLoc('${id}')`),chatFunctionItem('红包','redpacket',`cRed('${id}')`),chatFunctionItem('转账','money',`cTransfer('${id}')`),chatFunctionItem('多选删除','trash',`enterSelect('${id}','delete')`)
].join(''),second=[
  chatFunctionItem('名片','idcard',`cNamecard('${id}')`),chatFunctionItem('亲属卡','card',`cFamily('${id}')`),chatFunctionItem('授权查手机','spyphone',`cSpyGrant('${id}')`),chatFunctionItem('API路线','route','chatRouteQuickOpen()'),chatFunctionItem('多选转发','forward',`enterSelect('${id}')`),chatFunctionItem('文件','file',`cDoc('${id}')`),chatFunctionItem('骰子','dice',`cDice('${id}')`)
].join('');return `<div class="chat-function-viewport" id="chatFunctionViewport" onscroll="chatFunctionPanelScroll(this)"><section class="chat-function-page">${first}</section><section class="chat-function-page">${second}</section></div><div class="chat-panel-dots" aria-hidden="true"><i class="chat-panel-dot ${_chatFnPage===0?'on':''}"></i><i class="chat-panel-dot ${_chatFnPage===1?'on':''}"></i></div>`;}
function renderChat(id){const c=getC(id);if(!c)return '';
  if(S.wxLogin){if(!wxLoginActive())setTimeout(wxLogout,0);else{if(!_wxLoginTimer)wxLoginStartTimer();return wxLockedScreen();}}
  const bgSource=storedImageDisplaySource(c.chatBg),bg=bgSource?`background:url(${bgSource}) center/cover`:'';
  const body=chatMessageListHTML(id,c);
  const _naturalMood=wechatNaturalOn(),thought=visibleRoleThought(c),thoughtOpen=_naturalMood?'showInnerThought':'showMood';
  const mood=`<div class="moodbar chat-glass-mood" id="chatMoodBar" role="button" aria-expanded="false" onclick="toggleChatThought('${id}')" style="display:${S.settings.showMoodTag!==false?'flex':'none'};position:relative;align-items:center;flex-wrap:wrap;gap:6px;transition:border-radius .2s ease">${svgIc('thought',15,'currentColor')}<span id="chatMoodText" style="overflow:hidden;white-space:nowrap;text-overflow:ellipsis">${esc(thought?thought.slice(0,24):'…')}${thought.length>24?'…':''}</span>${chatThoughtPanelHTML(c)}</div>`;
  const visionBusy=hasPendingVision(id);
  const replyGenState=replyGenerationState(id);
  const qbar=quoteComposerHTML(id,c);
  const cohabBadge=cohabWechatNavBadge(c);
  return `<div class="nav chat-glass-nav ${cohabBadge?'cohab-wx-nav':''}"><span class="l" onclick="back()">‹</span><span class="t ${cohabBadge?'cohab-wx-title':''}"><style>/* WX_TITLE_TYPING_V1：他真在写回复时（原来三个点那段时间），顶上名字换成「对方正在输入…」，回完变回名字；聊天里不再冒三个点 */.wx-title-typing{display:none}.page:has(#chatbg #typing) .wx-title-name{display:none}.page:has(#chatbg #typing) .wx-title-typing{display:inline}#chatbg #typing{display:none!important}</style><b><span class="wx-title-name">${esc(c.remark||c.name)}</span><span class="wx-title-typing">对方正在输入…</span>${c.muted?' 🔕':''}</b>${roleBusyHeaderBadge(c)}${cohabBadge}</span><span class="r" onclick="go('contactInfo',{id:'${id}'})">⋯</span></div>
    ${mood}
    <div class="chatbg" id="chatbg" style="${bg}">${body}</div>
    <div class="panel chat-tools-panel" id="panel" data-page="${_panelPage}">
      <div class="chat-panel-pane chat-function-pane ${_panelPage==='emoji'?'':'on'}">${chatFunctionPanel(id)}</div>
      <div class="chat-panel-pane chat-emoji-pane ${_panelPage==='emoji'?'on':''}"><div class="ppage">${emojiPanel(id)}</div></div>
    </div>
    ${(_sel&&_sel.id===id)?`<div class="inputbar"><button class="btn g" style="flex:1" onclick="exitSelect()">取消</button>${_sel.mode==='delete'?`<button class="btn d" style="flex:1" onclick="delSelected('${id}')">删除(<span id="fwdcnt">${_sel.ids.length}</span>)</button>`:`<button class="btn" style="flex:1;background:#07c160;color:#fff" onclick="forwardSelected()">转发(<span id="fwdcnt">${_sel.ids.length}</span>)</button>`}</div>`:(S.couple&&S.couple.gags&&S.couple.gags[id])?`<div class="inputbar" style="justify-content:center;color:#fa5151;font-size:13px;padding:16px;text-align:center">ta把你们的聊天锁了，<span onclick="gagAskUnlock()" style="color:inherit;text-decoration:underline;cursor:pointer">去求他解锁</span></div>`:(manualReplySceneOn('wechat')&&!c.blocked?`<div class="manual-reply-row"><button class="manual-reply-chip" ${(replyGenState||visionBusy)?'disabled':''} onclick="manualReply('${id}')">${visionBusy?'正在识图…':replyGenState==='active'?'回复中…':replyGenState==='queued'?'排队中…':'▶ 让ta回'}</button></div>`:'')+qbar+`<div class="inputbar chat-inputbar${_voiceMode?' voice-on':''}">`+`
      <button type="button" class="chat-composer-icon chat-voice-toggle" aria-label="切换语音输入" onclick="chatVoiceToggle()">${chatVoiceButtonIcon()}</button>
      <textarea id="cinput" rows="1" placeholder="${c.blocked?'已拉黑，发不出去':(_voiceMode?'输入文字，发送为语音条…':'发消息…')}" ${c.blocked?'disabled':''}></textarea>
      <button type="button" class="chat-composer-icon chat-emoji-toggle" aria-label="打开表情" onclick="chatPanelToggle('emoji')">${chatEmojiButtonIcon()}</button>
      <button type="button" class="chat-composer-icon chat-function-toggle" aria-label="打开更多功能" onclick="chatPanelToggle('fn')"><span aria-hidden="true"></span></button>
      <button type="button" class="send chat-send" onclick="sendText('${id}')">${_voiceMode?'发语音':'发送'}</button>
    </div>`}`;}
/* 微信已读（v1412）：你发给角色的最后一条消息下面显示「未读 / 已读」，角色开始回你就变成已读。设置 → 角色、时间与消息 里可以随时关掉，关掉后真人好友那边也不显示、也不再告诉对方你读没读。 */
function readReceiptOn(){return !(S.settings&&S.settings.readReceipt===false);}
function readReceiptToggle(){S.settings.readReceipt=!readReceiptOn();save();render();toast(readReceiptOn()?'已开启微信已读':'已关闭微信已读');}
function roleReadCounted(m){return !!m&&!m._silent&&!m._call&&m.type!=='sys';}
function roleLastUserMsg(id){const a=msgs(id);for(let i=a.length-1;i>=0;i--){const m=a[i];if(!roleReadCounted(m))continue;if(m.role==='user')return m;}return null;}
function roleMsgRead(id,m){if(!m)return false;if(m.readAt)return true;const a=msgs(id);for(let i=a.length-1;i>=0;i--){const x=a[i];if(x===m)return false;if(roleReadCounted(x)&&x.role==='assistant')return true;}return false;}
/* 每一条都显示：读了就一直是已读，不会因为后面那条读了前面的就消失 */
function roleReadLabelHTML(c,m){if(!readReceiptOn()||!c||!m||m.role!=='user'||!roleReadCounted(m))return '';return `<div class="msgread msgread-line" data-read-for="${m.id}" data-wx-read="${roleMsgRead(c.id,m)?'已读':''}">${roleMsgRead(c.id,m)?'已读':''}</div>`;}
function roleLastRoleMsg(id){const a=msgs(id);for(let i=a.length-1;i>=0;i--){const m=a[i];if(!roleReadCounted(m))continue;if(m.role==='assistant')return m;}return null;}
/* 他发来的最后一条消息旁边显示你读没读：你打开聊天看到了就变成已读 */
function roleSeenLabelHTML(c,m){if(!readReceiptOn()||!c||!m||m.role!=='assistant'||!roleReadCounted(m))return '';return `<div class="msgread msgread-line" data-seen-for="${m.id}" data-wx-read="${m.seenAt?'已读':''}">${m.seenAt?'已读':''}</div>`;}
function roleReadRefresh(id){const cb=$('#chatbg');if(!cb)return;const els=cb.querySelectorAll('.msgread');if(!els.length)return;const a=msgs(id),on=readReceiptOn(),byId=new Map(),pos=new Map();a.forEach((m,i)=>{if(m&&m.id){byId.set(m.id,m);pos.set(m.id,i);}});let lastRoleIdx=-1;for(let i=a.length-1;i>=0;i--){if(roleReadCounted(a[i])&&a[i].role==='assistant'){lastRoleIdx=i;break;}}
  els.forEach(el=>{el.style.display=on?'':'none';if(!on)return;const sid=el.dataset.seenFor,rid=el.dataset.readFor,m=byId.get(sid||rid);if(!m)return;const t=sid?(m.seenAt?'已读':''):((m.readAt||pos.get(rid)<lastRoleIdx)?'已读':'');if(typeof wechatMotionReadLabel==='function')wechatMotionReadLabel(el,t);else if(el.textContent!==t)el.textContent=t;});}
function roleSeenTick(){if(document.hidden||S.me.locked||typeof cur!=='function')return;const k=cur();if(!k||k.p!=='chat'||!k.id)return;const a=msgs(k.id),now=Date.now();let ch=false;for(let i=a.length-1;i>=0;i--){const m=a[i];if(!roleReadCounted(m)||m.role!=='assistant'||m.seenAt)continue;if(!m._seenPending){m._seenPending=now;continue;}if(now-m._seenPending>=700){m.seenAt=now;delete m._seenPending;ch=true;}}if(ch){wxMarkPageSeen(k);save(1500);roleReadRefresh(k.id);}}
setInterval(roleSeenTick,500);
/* 角色开始回你（出现正在输入）那一刻算他读了 */
/* 标完已读后直接改界面上的字，不用整页重画 */
function pfReadInPlace(id){if(!readReceiptOn())return;const p=phoneFriendState(),me=(''+p.id).toUpperCase(),arr=pfMsgList(p.messages,(''+id).toUpperCase());if(!arr.length)return;const byId=new Map(arr.map(m=>[m&&m.id,m]));document.querySelectorAll('[data-pf-in]').forEach(el=>{const m=byId.get(el.dataset.pfIn);if(m&&pfReadIds(m).indexOf(me)>=0){if(typeof wechatMotionReadLabel==='function')wechatMotionReadLabel(el,'已读');else if(el.textContent!=='已读')el.textContent='已读';}});}
function pfLastIncoming(arr,pid){if(!Array.isArray(arr))return null;for(let i=arr.length-1;i>=0;i--){const x=arr[i];if(x&&x.from!==pid&&!x.recalled&&!x._transferReceipt)return x;}return null;}
function roleReadPrompt(c){if(!readReceiptOn()||!c)return '';const a=msgs(c.id);let last=null;for(let i=a.length-1;i>=0;i--){if(roleReadCounted(a[i])){last=a[i];break;}}if(!last||last.role!=='assistant'||!last.seenAt)return '';const min=Math.floor((Date.now()-last.seenAt)/60000);if(min<2)return '';return '\n\n# 已读\n微信开着已读：你发的最后一条消息，'+S.me.name+'在'+(min<60?min+'分钟':Math.floor(min/60)+'小时')+'前已经读了，但还没回你。你知道这件事，可以按人设自然地在意或不在意，别每次都提。';}
