function roleTextTranslationPrompt(source){return[{role:'system',content:'你是微信消息翻译器。把用户提供的文字准确、自然地翻译成简体中文；保留称呼、语气、标点、换行和 emoji，不补充解释，不审查，不回答消息，只输出译文。'},{role:'user',content:String(source||'').slice(0,1600)}];}
function roleTextTranslationBatchPrompt(sources){return[{role:'system',content:'你是微信消息翻译器。用户会给出若干条带编号的消息，把每一条分别准确、自然地翻译成简体中文；保留称呼、语气、标点、换行和 emoji，不补充解释，不审查，不回答消息。必须逐条翻译、一条不漏，不要合并或拆分：每条译文另起一行，以原编号开头，格式为「[编号] 译文」。只输出这些带编号的译文。'},{role:'user',content:sources.map((x,i)=>'['+(i+1)+'] '+String(x||'').slice(0,1600)).join('\n\n')}];}
